43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE = 0.1;
45	const SWORD_BASE_PREMIUM = 100;
46	
47	const quote = (step: QuoteStep): StepResult => {
48	  const basePremium = step.items.length * SWORD_BASE_PREMIUM;
49	  const premium =
50	    basePremium + basePremium * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
51	
52	  return { premium };
53	};
54	
55	export const runScenario = (scenario: Scenario): ScenarioResult => {
56	  return { results: scenario.steps.map((step) => quote(step as QuoteStep)) };
57	};
